CREATE DATABASE IF NOT EXISTS nml_ich_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE nml_ich_portal;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,employee_id VARCHAR(80),department VARCHAR(120),email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS complaints(id INT AUTO_INCREMENT PRIMARY KEY,complaint_code VARCHAR(32) UNIQUE NOT NULL,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,department VARCHAR(120) NOT NULL,category VARCHAR(100) NOT NULL,description TEXT NOT NULL,status ENUM('Pending','In Progress','Resolved','Rejected') DEFAULT 'Pending',admin_remarks TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);